#include <torch/extension.h>
torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void max_reduce_dim1_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int Outer, int Reduce, int Inner)
{
  int64_t total  = (int64_t)Outer * (int64_t)Inner;
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (; idx < total; idx += stride) {
    int b = (int)(idx / Inner);
    int i = (int)(idx % Inner);
    // Base pointer for this (b, i) column; consecutive threads (varying i)
    // access contiguous addresses for a fixed r, so this stays coalesced.
    const T* __restrict__ base =
        X + (int64_t)b * (int64_t)Reduce * (int64_t)Inner + (int64_t)i;
    T maxval;
    if (Reduce >= 8) {
      T acc0 = __ldg(base);
      T acc1 = __ldg(base + (int64_t)Inner);
      T acc2 = __ldg(base + (int64_t)2 * Inner);
      T acc3 = __ldg(base + (int64_t)3 * Inner);
      T acc4 = __ldg(base + (int64_t)4 * Inner);
      T acc5 = __ldg(base + (int64_t)5 * Inner);
      T acc6 = __ldg(base + (int64_t)6 * Inner);
      T acc7 = __ldg(base + (int64_t)7 * Inner);
      int r = 8;
      #pragma unroll 4
      for (; r + 7 < Reduce; r += 8) {
        T v0 = __ldg(base + (int64_t)r * (int64_t)Inner);
        T v1 = __ldg(base + (int64_t)(r + 1) * (int64_t)Inner);
        T v2 = __ldg(base + (int64_t)(r + 2) * (int64_t)Inner);
        T v3 = __ldg(base + (int64_t)(r + 3) * (int64_t)Inner);
        T v4 = __ldg(base + (int64_t)(r + 4) * (int64_t)Inner);
        T v5 = __ldg(base + (int64_t)(r + 5) * (int64_t)Inner);
        T v6 = __ldg(base + (int64_t)(r + 6) * (int64_t)Inner);
        T v7 = __ldg(base + (int64_t)(r + 7) * (int64_t)Inner);
        acc0 = v0 > acc0 ? v0 : acc0;
        acc1 = v1 > acc1 ? v1 : acc1;
        acc2 = v2 > acc2 ? v2 : acc2;
        acc3 = v3 > acc3 ? v3 : acc3;
        acc4 = v4 > acc4 ? v4 : acc4;
        acc5 = v5 > acc5 ? v5 : acc5;
        acc6 = v6 > acc6 ? v6 : acc6;
        acc7 = v7 > acc7 ? v7 : acc7;
      }
      T m01 = acc0 > acc1 ? acc0 : acc1;
      T m23 = acc2 > acc3 ? acc2 : acc3;
      T m45 = acc4 > acc5 ? acc4 : acc5;
      T m67 = acc6 > acc7 ? acc6 : acc7;
      T m0123 = m01 > m23 ? m01 : m23;
      T m4567 = m45 > m67 ? m45 : m67;
      maxval = m0123 > m4567 ? m0123 : m4567;
      for (; r < Reduce; ++r) {
        T v = __ldg(base + (int64_t)r * (int64_t)Inner);
        maxval = v > maxval ? v : maxval;
      }
    } else if (Reduce >= 4) {
      T acc0 = __ldg(base);
      T acc1 = __ldg(base + (int64_t)Inner);
      T acc2 = __ldg(base + (int64_t)2 * Inner);
      T acc3 = __ldg(base + (int64_t)3 * Inner);
      int r = 4;
      #pragma unroll 4
      for (; r + 3 < Reduce; r += 4) {
        T v0 = __ldg(base + (int64_t)r * (int64_t)Inner);
        T v1 = __ldg(base + (int64_t)(r + 1) * (int64_t)Inner);
        T v2 = __ldg(base + (int64_t)(r + 2) * (int64_t)Inner);
        T v3 = __ldg(base + (int64_t)(r + 3) * (int64_t)Inner);
        acc0 = v0 > acc0 ? v0 : acc0;
        acc1 = v1 > acc1 ? v1 : acc1;
        acc2 = v2 > acc2 ? v2 : acc2;
        acc3 = v3 > acc3 ? v3 : acc3;
      }
      T m01 = acc0 > acc1 ? acc0 : acc1;
      T m23 = acc2 > acc3 ? acc2 : acc3;
      maxval = m01 > m23 ? m01 : m23;
      for (; r < Reduce; ++r) {
        T v = __ldg(base + (int64_t)r * (int64_t)Inner);
        maxval = v > maxval ? v : maxval;
      }
    } else {
      maxval = __ldg(base);
      for (int r = 1; r < Reduce; ++r) {
        T v = __ldg(base + (int64_t)r * (int64_t)Inner);
        maxval = v > maxval ? v : maxval;
      }
    }
