torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  int64_t ndim = x.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
  auto x_c = x.contiguous();
  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
  int64_t reduce_size = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < ndim; ++d) inner *= x_c.size(d);
  std::vector<int64_t> out_shape;
  for (int64_t d = 0; d < ndim; ++d) {
    if (d != dim) out_shape.push_back(x_c.size(d));
  }
  auto y = torch::empty(out_shape, x_c.options());
  constexpr int Threads = 256;
  int64_t total = outer * inner;
  int64_t blocks_needed = (total + Threads - 1) / Threads;
  int64_t max_blocks = 65535;
  int blocks = (int)(blocks_needed < max_blocks ? blocks_needed : max_blocks);
  if (blocks < 1) blocks = 1;
  dim3 block(Threads);
  dim3 grid((unsigned)blocks);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  AT_DISPATCH_FLOATING_TYPES(x_c.scalar_type(), "max_reduce_dim1_kernel", ([&] {
    max_reduce_dim1_kernel<scalar_t><<<grid, block, 0, stream>>>(
        x_c.data_ptr<scalar_t>(),
        y.data_ptr<scalar_t>(),
        (int)outer, (int)reduce_size, (int)inner
    );
  }));
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

max_reduce_ext = load_inline(
    name="cute_max_reduce_dim_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["max_reduce_dim_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Max reduction over a specific dimension,
    implemented with a custom CUTE-based CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = max_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_dim_forward(x, self.dim)

